import pathlib,json
out=pathlib.Path(__file__).resolve().parent
u=json.loads((out/'unit-analysis.json').read_text());delta=json.loads((out/'delta.json').read_text());prov=json.loads((out/'provenance.json').read_text());native=json.loads((out/'concatenate-native-base.json').read_text());nh=json.loads((out/'concatenate-native-head.json').read_text());stock=json.loads((out/'concatenate.json').read_text())
assert native==nh and native['checker_diagnostics']==0

def rel(s):return 'src/'+s.split('/src/',1)[1] if '/src/' in s else s
def esc(s):return str(s).replace('|','\\|').replace('\r','').replace('\n','<br>')
def stop(f):return 'No lowering stop' if not f else f"{f['kind']}: {f['reason']} at {rel(f['where'])}"
def unit(r):return r['unit'].get('name',r['unit']['kind'])
def table(headers,rows):return '\n'.join(['| '+' | '.join(headers)+' |','| '+' | '.join(['---']*len(headers))+' |',*['| '+' | '.join(esc(c) for c in r)+' |' for r in rows]])+'\n'
lines=['# Paired latent census: overload proof 3a7ea290 against 17c6378d','',f"Base `{prov['base']}`; head `{prov['head']}`. The head is exactly one commit over its base. Report and evidence only; no compiler or adaptation edits.",'','## 1. Regressions','']
raw=delta['raw_findings'];distinct=delta['distinct_reads']
regs=raw['regressions'];unitregs=[r for r in regs if r['type']=='previously_finding_free_unit'];panicregs=[r for r in regs if r['type']=='new_panic'];scanregs=[r for r in regs if r['type']=='previously_finding_free_scan_site']
lines.append(f"Previously finding-free units that stop on head: **{len(unitregs)}**. New panics: **{len(panicregs)}**. New refusal-scan sites: **{len(scanregs)}**. Raw regression entries: {len(regs)}; distinct: {len(distinct['regressions'])}.")
if unitregs:lines+=['',table(['Unit','Unit location','Head first stop'],[[unit(r),rel(r['unit']['where']),stop(r['head'])] for r in unitregs])]
if panicregs:lines+=['',table(['Panic location','Reason'],[[rel(r['finding']['where']),r['finding']['reason']] for r in panicregs])]
if scanregs:lines+=['',table(['Scan location','Reason'],[[rel(r['finding']['where']),r['finding']['reason']] for r in scanregs])]
if not regs:lines+=['','There are no regressions to name.']
lines+=['','## 2. Cleared, moved and new findings','',table(['Paired delta','Raw','Distinct outermost accesses'],[[label,len(raw[k]),len(distinct[k])] for label,k in [('Cleared: no finding remains at identity','lowered'),('Moved: old reason gone, another remains','moved'),('New findings','new_findings'),('New sites','new_sites'),('Changed unit first stops','unit_first_stop_delta'),('Regressions','regressions')]]),'Distinct identities use the unmodified base `stage3/census/pair` tool: source path, source SHA-256, outermost contiguous property/element access start, and exact reason. Raw identities retain kind, source position, reason and text. New reasons in already-blocked units are findings, not automatically regressions. Full ledgers: [delta.json](delta.json) and [pair-report.md](pair-report.md).','',table(['Measure','Base','Head'],[['Resolved source files',len(u['header']['sources']),len(u['header']['sources'])],['Checker diagnostics',0,0],['Units',u['units'],u['units']],['Attempted units',u['attempted_base'],u['attempted_head']],['Attempted units with no first stop',u['no_stop_base'],u['no_stop_head']],['Overload-result first stops',u['overload_result_base'],u['overload_result_head']]]),'',table(['Finding kind','Base raw','Head raw','Base distinct','Head distinct'],[[kind,raw['totals']['before'].get(kind,0),raw['totals']['after'].get(kind,0),distinct['totals']['before'].get(kind,0),distinct['totals']['after'].get(kind,0)] for kind in sorted(set(raw['totals']['before'])|set(raw['totals']['after']))]),'','## 3. The five concatenate units','','Overload indexes are **one-based among the eight overload declarations**, excluding the implementation. Both sides’ own pinned Adamic checker resolve the same call to the same declaration with zero diagnostics. Stock TypeScript independently agrees; its separate host-type diagnostics are retained in `concatenate.json` and are not the census diagnostics.','']
resolved=[]
for r in u['concatenate']:
 st=next(x for x in stock['results'] if x['unit']['where']==r['unit']['where']);assert len(st['calls'])==1
 call=st['calls'][0];ns=[x for x in native['calls'] if x['where']==call['where'] and x['unit']==r['unit']['where']];assert len(ns)==1;n=ns[0]
 assert n['index']==call['resolved_declaration']['index'] and n['declaration_text']==call['resolved_declaration']['text']
 resolved.append([unit(r),rel(r['unit']['where']),rel(n['where'])+' — '+n['text'],str(n['index'])+' / 8',n['declaration_text'],stop(r['base']),stop(r['head'])])
lines.append(table(['Unit','Unit location','Call site and text','Resolved overload','Resolved declaration text','Base first stop','Head first stop'],resolved))
lines+=['','The declaration-level stop checks the overload set; it does not identify the overload selected by that call. Native evidence for both sides is in `concatenate-native-{base,head}.json`; call/declaration evidence is in [concatenate.json](concatenate.json).','','## 4. getSupportedExtensions and writeTokenText','','Each row gives the first stop on each side, preserving its exact reason words. Where the old guard clears, the head column names the next observed stop; an unchanged guard means no next stop was reached. Locations are one-based lines and UTF-16 columns.','',table(['Unit','Unit location','Base first stop','Head first / next stop'],[[unit(r),rel(r['unit']['where']),stop(r['base']),stop(r['head'])] for r in u['getSupportedExtensions']+u['writeTokenText']]),'','## 5. The historical 43 overload-result stops','']
c=u['historical_43'];clear_b=sum(r['result_stop_clear_base'] for r in c);clear_h=sum(r['result_stop_clear_head'] for r in c)
lines +=[f"**{clear_b}/43 clear at base; {clear_h}/43 clear at head**, using the earlier census’s criterion: the unit no longer first-stops on an overload-result refusal. This is not a claim that all these units lower. Exact historical definitions are in [historical-43.json](historical-43.json); mapping uses source file, declaration kind, function name and ordinal among same-named declarations.",'',table(['Unit','Current unit location','Base first stop','Head first stop'],[[unit(r),rel(r['unit']['where']),stop(r['base']),stop(r['head'])] for r in c]),'','## Method, bounds and validation','','Both scratch overlays are generated from their **own side’s tree**, including each side’s own `make_overlay.py` and `entry_overlay.py`. Both trees have identical meter instrumentation. No earlier measurement stream is reused. Both compilers use their exact recursive submodule pins. The adaptation-input diff is empty (see `adaptation-input-diff.txt`); the full head diff touches only four `internal/lower` files. Both sides read the single immutable tree produced by **17c6378d’s stage3/apply.sh**, pinned to TypeScript 6.0.3 `050880ce59e30b356b686bd3144efe24f875ebc8`. Source hashes and overlay provenance are retained.','','As in 83e07d2f, this is the entry-root **first-error** latent census (`LATENT_FULL=0`, `LATENT_ASSERT_NO_OUTPUT=1`), with per-unit eligibility, findings and timings. Ordinary Load and Lower remain disabled; no backend or usable IR is produced. A unit with no finding is not proof of complete compilation.','','To meet the 30-minute process limit, each side runs eight disjoint attempted-unit shards over the complete project. Selection occurs after existing checker-body skips and generic deferral, before an independent attempt; it does not alter declarations, dependencies or eligibility. Shards 0 and 1 retain complete refusal scans; a scratch selector omits duplicate scans in shards 2–7. Both own-side overlay variants and executable hashes are retained. The two complete scan ledgers must agree exactly. Deferred/skipped unit records are repeated and deduplicated. Generic call witnesses are unioned using the original Go ordering and five-witness cap. Each attempted unit must occur exactly once; a stock-parser inventory checks every top-level unit and its source order. Shard relation-cache reports are process-scoped, retained separately, and never summed. The merger stops on any relation overflow or global finding.','','Both binary variants on both sides passed the unsharded-versus-sharded fixture, including a real overloaded-value stop and cross-shard generic witnesses; both existing latent audits and all 20 pairing tests passed. The composition fixture validates this measurement mechanism on a bounded example, rather than claiming an unmeasured full unsharded run.','','Two shards per side run concurrently with `GOMEMLIMIT=3GiB`. Every timing wrapper records its actual child status and exits with it (signals use the shell encoding). Each census child is terminated at 1,740 seconds, with at most 10 seconds to kill, so no child or wrapper reaches 30 minutes. No measured process timed out. `run.py`, `build.sh`, `measure.sh`, `measure-scan.sh`, `shard_overlay.py`, `scan_overlay.py`, `build-scan.sh`, `merge.py`, `analyze.py`, `report.py`, and `commands.md` retain the method. Go evidence is named `.go.txt`.','']
# Retain the small complete changed-finding ledger directly in the report.
pos=lines.index('## 3. The five concatenate units')
ledger=['Cleared raw finding identities (the distinct view also clears three):','',table(['Location','Kind','Exact reason'],[[rel(r['base']['where']),r['base']['kind'],r['base']['reason']] for r in raw['lowered']]),'New raw findings (the distinct view also has three):','',table(['Location','Kind','Exact reason'],[[rel(r['finding']['where']),r['finding']['kind'],r['finding']['reason']] for r in raw['new_findings']])]
other=[r for r in u['first_stop_changes'] if r['unit']['where'] not in {x['unit']['where'] for x in u['concatenate']+u['getSupportedExtensions']+u['writeTokenText']}]
if other: ledger+=['Other changed unit first stops:','',table(['Unit','Unit location','Base first stop','Head first stop'],[[unit(r),rel(r['unit']['where']),stop(r['base']),stop(r['head'])] for r in other])]
lines[pos:pos]=ledger+['']
# Interpret only the freshly measured supported-extension records.
if all(r['base'] and r['head'] and tuple(r['base'][k] for k in ('kind','where','reason'))==tuple(r['head'][k] for k in ('kind','where','reason')) for r in u['getSupportedExtensions']):
 pos=lines.index('## 5. The historical 43 overload-result stops')
 lines[pos:pos]=['All five getSupportedExtensions-blocked units retain the same overload-result first stop on this head. **No next stop is observed for these five, including no `adamic/invariant-mutable` stop.**', '', 'The adapted implementation contains `x.extension as Extension` in its later callback. The pinned head’s proof scans the entire body and rejects an `AsExpression` before its flow reasoning. See [the adapted implementation excerpt](get-supported-extensions-source.json), [overload-proof-head.go.txt](overload-proof-head.go.txt), and the retained source hashes and first-stop records.', '']
# Own-process stats, never supervisor elapsed or combined RSS.
stats=[]
for side in ['base','head']:
 for i in range(8):
  d=json.loads((out/side/('shard-'+str(i)+'.time.json')).read_text());assert d['exit_code']==0 and not d['timed_out'] and d['wall_seconds']<1800
  stats.append([side,i,round(d['wall_seconds'],3),round(d['user_seconds'],3),round(d['system_seconds'],3),round(d['peak_rss_kib']/1024,2),d['exit_code']])
lines +=['Census child measurements (overlapping runs; RSS is each child’s own peak):','',table(['Side','Shard','Wall s','User s','System s','Peak RSS MiB','Child exit'],stats)]
(out/'REPORT.md').write_text('\n'.join(lines).rstrip()+'\n')
print('report written; historical clears',clear_b,clear_h,'regressions',len(regs))
